def icon(name, extra=''):
    return f'<svg class="icon {extra}" viewBox="0 0 24 24" aria-hidden="true">{ICONS[name]}</svg>'

def button(name, label, extra=''):
    return f'<button class="icon-button {extra}" aria-label="{label}" title="{label}">{icon(name)}</button>'

def forge(size=''):
    return f'<span class="forge-mark {size}" aria-hidden="true"><svg viewBox="0 0 28 28"><path d="M6 5h17v5H11v4h10v5H11v6H6Z"/></svg></span>'

def pwmark():
    return f'<span class="pw-mark">{icon("key")}</span>'

def login_row(kind, selected=False, compact=False):
    work = kind == 'work'
    name, email, vault = ('Forge — work', 'octocat@studio.example', 'Work vault') if work else ('Forge — personal', 'octocat@personal.example', 'Personal vault')
    return f'''<button class="login-row {'selected' if selected else ''} {'compact' if compact else ''}" aria-label="Fill {name}, {email}, {vault}">
      {forge()}<span class="login-details"><span class="login-title">{name}</span><span class="login-email">{email}</span><span class="vault">{icon('vault')}{vault}</span></span>
      <span class="row-action">{icon('return' if selected else 'arrow')}</span></button>'''

