def shell(variant):
    inline = variant == 'b'
    return f'''<main class="window" aria-label="Rail browser design mockup, synthetic data">
    <nav class="rail" aria-label="Spaces"><img class="rail-mark" src="__MARK__" alt="Rail">
      <button class="rail-button active" aria-label="Work Space">{icon('briefcase')}</button><button class="rail-button" aria-label="Personal Space">{icon('home')}</button><button class="rail-button" aria-label="Reading Space">{icon('book')}</button>
      <div class="rail-bottom"><button class="rail-button" aria-label="Add Space">{icon('plus')}</button><button class="rail-button" aria-label="Settings">{icon('sliders')}</button></div></nav>
    <aside class="sidebar"><div class="traffic" aria-hidden="true"><span></span><span></span><span></span></div><div class="brand">Rail</div><div class="space-head">Work{icon('more')}</div>
      <div class="side-row">{icon('grid')}<span class="text">Projects</span></div><div class="side-row">{icon('branch')}<span class="text">Activity</span></div>
      <div class="side-label">Pinned</div><div class="pinned"><div class="pin">{icon('code')}GitHub</div><div class="pin">{icon('file')}Docs</div><div class="pin">{icon('globe')}Calendar</div><div class="pin">{icon('grid')}Design</div></div>
      <div class="side-label">Tabs</div><div class="side-row selected">{forge('tab-forge')}<span class="text">Sign in to Forge</span><span class="session-badge">W</span></div>
      <div class="side-row">{icon('code')}<span class="text">Rail · GitHub</span><span class="session-badge">W</span></div><div class="side-row">{icon('globe')}<span class="text">localhost:3000</span><span class="session-badge">W</span></div><div class="side-row">{icon('file')}<span class="text">Design notes</span>{icon('moon')}</div><div class="side-row">{icon('plus')}<span class="text">New tab</span></div>
      <div class="side-footer">{icon('moon')}1 tab asleep</div></aside>
    <section class="content"><header class="toolbar">{button('sidebar','Toggle sidebar')}{button('back','Back')}{button('forward','Forward','quiet')}{button('reload','Reload')}
      <div class="address">{icon('lock')}<span>console.forge.example<span class="path"> / login</span></span></div>{button('key','Fill with 1Password','password-button '+('pressed' if variant in ('a','c') else ''))}{button('download','Downloads')}<div class="toolbar-sep"></div><button class="session-picker">Work{icon('down')}</button></header>
      <div class="website"><div class="site-nav"><div class="site-brand">{forge()}Forge</div><span class="help-link">Need help?{icon('external')}</span></div>
        <form class="login-form" onsubmit="return false"><h1>Welcome back.</h1><p class="site-intro">Sign in to your Forge workspace.</p><label class="site-label" for="email">Email address</label><div class="site-input {'focused' if inline else ''}"><input id="email" type="text" placeholder="you@company.com" readonly>{f'<button type="button" class="inline-trigger" aria-label="Fill with 1Password">{icon("key")}</button>' if inline else ''}</div>
        <label class="site-label" for="password">Password<a href="#" tabindex="-1">Forgot password?</a></label><div class="site-input"><input id="password" type="password" placeholder="Enter your password" readonly></div><button class="site-submit" type="button">Sign in</button><div class="site-divider">or</div><button class="site-sso" type="button">Continue with SSO</button><div class="site-signup">New to Forge? <a href="#" tabindex="-1">Create an account</a></div></form>
        <div class="site-footer"><span>Privacy</span><span>Terms</span><span>Contact</span></div>{inline_picker() if inline else ''}</div>
      <footer class="statusbar"><span>Work session</span><span>Idle tabs unload after 10 min</span></footer></section>
      {toolbar_picker() if variant == 'a' else command_picker() if variant == 'c' else ''}</main>'''

def toolbar_picker():
    return f'''<section class="surface popover" aria-label="1Password login picker"><header class="picker-header">{pwmark()}<div><div class="picker-name">1Password</div><div class="domain">{icon('lock')}console.forge.example</div></div>{button('sliders','1Password settings','header-end')}</header>
    <div class="search-field">{icon('search')}<input aria-label="Filter matching logins" placeholder="Find a login for this website" readonly></div><div class="list-heading"><span>Matching logins</span><span>2</span></div><div class="login-list">{login_row('work',True)}{login_row('personal')}</div>
    <div class="picker-action"><button class="fill-button">Fill login{icon('return')}</button></div><footer class="picker-footer"><button>Open 1Password{icon('external')}</button><span class="key-hint"><span class="keycap">esc</span>Close</span></footer></section>'''

def inline_picker():
    return f'''<section class="surface inline-picker" aria-label="1Password suggestions"><header class="picker-header">{pwmark()}<div class="picker-name">Fill with 1Password</div></header><div class="inline-domain">{icon('lock')}console.forge.example</div>
    <div class="login-list">{login_row('work',True,True)}{login_row('personal',False,True)}</div><footer class="picker-footer"><button>Open login picker{icon('arrow')}</button><span class="key-hint"><span class="keycap">↵</span>Fill</span></footer></section>'''

def command_picker():
    return f'''<div class="scrim"></div><section class="surface command-picker" aria-label="Fill with 1Password command picker"><header class="picker-header">{pwmark()}<div><div class="picker-name">Fill with 1Password</div><div class="domain">{icon('lock')}console.forge.example</div></div><span class="close-hint"><span class="keycap">esc</span></span></header>
    <div class="search-field">{icon('search')}<input aria-label="Search matching logins" placeholder="Search logins for this website…" readonly></div><div class="list-heading"><span>Matching logins</span><span>2</span></div><div class="login-list">{login_row('work',True)}{login_row('personal')}</div>
    <footer class="picker-footer"><div class="footer-navigation"><span class="key-hint"><span class="keycap">↑</span><span class="keycap">↓</span>Choose</span><button>Open 1Password{icon('external')}</button></div><button class="fill-button mini-fill">Fill login{icon('return')}</button></footer></section>'''

def main():
    font = 'data:font/woff2;base64,' + base64.b64encode((HERE/'manrope-ui.woff2').read_bytes()).decode()
    mark = str(ROOT/'design/icon/rail-r/AppIcon-1024.png')
    for variant, name in [('a','toolbar-popover'),('b','inline-suggestion'),('c','keyboard-picker')]:
        html = f'<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Rail · 1Password · {name}</title><style>{CSS}</style></head><body>{shell(variant)}</body></html>'
        html = html.replace('__FONT__',font).replace('__MARK__',mark)
        (HERE/f'{variant}-{name}.html').write_text(html)
    print('Wrote three mockup HTML files.')

if __name__ == '__main__':
    main()
